-- Service Desk's part of the workspace demo (AGENT_DATA_ACCESS_PLAN.md, "Demo data"). The platform
-- loads the shared demo first (the demo team, the 15 customers with contacts and areas, the
-- catalogue), then calls load_demo() here as postgres; unload_demo() takes it out again. Every demo
-- row has a demo id (core.demo_uuid), so real records are never touched.
--
-- Their machines, ~3 months of closed complaints (parts and charges), 7 pending today (3 older than
-- two days, 4 with Ramesh, 1 not yet assigned), and AMC contracts - 5 expiring in the next few weeks
-- and 2 that lapsed last week without renewal. Sharma Traders (Canon iR 2525): 3 visits in 3
-- months, 2 of them paper jams - the CRM's upgrade deal for them follows from that.
-- The service team: Neha Gupta (service manager: dispatcher and engineer), Ramesh, Imran, Vikas.

CREATE OR REPLACE FUNCTION __APP_SCHEMA__.load_demo() RETURNS void
LANGUAGE plpgsql SET search_path = __APP_SCHEMA__, pg_temp AS $$
DECLARE
  today date := __APP_SCHEMA__.today();
  cust uuid;
BEGIN
  -- Loading twice changes nothing
  IF EXISTS (SELECT 1 FROM __APP_SCHEMA__.complaints WHERE core.is_demo(id)) THEN RETURN; END IF;
  PERFORM set_config('app.via', 'demo', true);
  PERFORM core.add_demo_member('__APP_SCHEMA__', core.demo_person('neha'), ARRAY['dispatcher', 'engineer']);
  PERFORM core.add_demo_member('__APP_SCHEMA__', core.demo_person('ramesh'), ARRAY['engineer']);
  PERFORM core.add_demo_member('__APP_SCHEMA__', core.demo_person('imran'), ARRAY['engineer']);
  PERFORM core.add_demo_member('__APP_SCHEMA__', core.demo_person('vikas'), ARRAY['engineer']);
  cust := core.demo_id(3, 1);
  cust := core.demo_id(3, 2);
  cust := core.demo_id(3, 3);
  cust := core.demo_id(3, 4);
  cust := core.demo_id(3, 5);
  cust := core.demo_id(3, 6);
  cust := core.demo_id(3, 7);
  cust := core.demo_id(3, 8);
  cust := core.demo_id(3, 9);
  cust := core.demo_id(3, 10);
  cust := core.demo_id(3, 11);
  cust := core.demo_id(3, 12);
  cust := core.demo_id(3, 13);
  cust := core.demo_id(3, 14);
  cust := core.demo_id(3, 15);
END $$;

CREATE OR REPLACE FUNCTION __APP_SCHEMA__.unload_demo() RETURNS void
LANGUAGE plpgsql SET search_path = __APP_SCHEMA__, pg_temp AS $$
BEGIN
  PERFORM set_config('app.via', 'demo', true);
  -- Every DELETE needs a WHERE (Supabase's safeupdate); history goes with its complaint
  DELETE FROM __APP_SCHEMA__.amc_contracts WHERE core.is_demo(id);
  DELETE FROM __APP_SCHEMA__.complaints WHERE core.is_demo(id);
  DELETE FROM __APP_SCHEMA__.machines WHERE core.is_demo(id);
END $$;

REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.load_demo() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.unload_demo() FROM PUBLIC, anon, authenticated;
